using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Mbb.Archive.Modules.Search.Infrastructure.Persistence.Indexing;
namespace Mbb.Archive.Modules.Search.Infrastructure.Persistence.Configurations;
internal sealed class SearchIndexRequestConfiguration:IEntityTypeConfiguration<SearchIndexRequest>{public void Configure(EntityTypeBuilder<SearchIndexRequest>b){b.ToTable("index_requests",SearchSchema.Name);b.HasKey(x=>x.DocumentId);b.Property(x=>x.DocumentId).HasColumnName("document_id").ValueGeneratedNever();b.Property(x=>x.ProjectionRevision).HasColumnName("projection_revision");b.Property(x=>x.RequestedAt).HasColumnName("requested_at");b.Property(x=>x.NextAttemptAt).HasColumnName("next_attempt_at");b.Property(x=>x.IndexedAt).HasColumnName("indexed_at");b.Property(x=>x.DeadLetteredAt).HasColumnName("dead_lettered_at");b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.LastError).HasColumnName("last_error").HasMaxLength(4000);b.Property(x=>x.LockedBy).HasColumnName("locked_by").HasMaxLength(200);b.Property(x=>x.LockedUntil).HasColumnName("locked_until");b.HasIndex(x=>new{x.IndexedAt,x.DeadLetteredAt,x.NextAttemptAt}).HasDatabaseName("ix_search_index_requests_dispatch");}}
